// UIKit: animate a constraint
heightConstraint.constant = isExpanded ? 240 : 80
UIView.animate(withDuration: 0.35, delay: 0,
               usingSpringWithDamping: 0.8, initialSpringVelocity: 0) {
    self.view.layoutIfNeeded()
}

// SwiftUI
struct Card: View {
    @State private var expanded = false
    var body: some View {
        VStack {
            Text("Details")
            if expanded { Text("More info").transition(.opacity.combined(with: .move(edge: .top))) }
        }
        .onTapGesture { withAnimation(.spring) { expanded.toggle() } }
    }
}
